const packageName='oauth-records-v1';
check((await read('/api/packages')).packages.length===0,'The initial workflow expects the retained empty merchant workspace; inspect existing packages before repeating it.');
await page.locator('#file').setInputFiles(ready.specPath);
await settled();
check((await page.locator('#source-summary').innerText()).includes('Records API'),'The original source did not load into the merchant workspace.');
await page.locator('#seller-server').fill(ready.publicSellerServer);
await page.locator('#service-name').fill('Records access');
await page.locator('#network').fill(ready.paymentExample.network);
await page.locator('#asset').fill(ready.paymentExample.asset);
await page.locator('#recipient').fill(ready.paymentExample.payTo);
await page.locator('#payment-timeout').fill(String(ready.paymentExample.maxTimeoutSeconds));
await page.locator('#allow-loopback').check();
await page.getByRole('checkbox',{name:'Select GET /records',exact:true}).check();
const card=page.locator('#routes article.route').first();
await card.getByLabel('Price in atomic units',{exact:true}).fill(ready.paymentExample.amountAtomic);
await card.locator('summary').filter({hasText:'Backend OAuth authorization'}).click();
await card.getByLabel('Declared OAuth flow',{exact:true}).selectOption('authorizationCode');
await card.locator('summary').filter({hasText:'Shared read results'}).click();
await card.getByLabel('Share this read-only result across buyers with the same request',{exact:true}).check();
await card.getByLabel('Maximum freshness, milliseconds',{exact:true}).fill('60000');
const authorization=await authorize(ready.alias);
await card.getByRole('combobox',{name:'Provider connection for GET /records',exact:true}).selectOption(ready.alias);
const binding=await clickApi(card.getByRole('button',{name:'Use reviewed grant for GET /records',exact:true}),'/api/oauth/binding');
check(binding.body.oauthConnection.grantId===authorization.grantId,'The route selected another reviewed grant.');
const preview=await clickApi(page.locator('#preview'),'/api/preview');
check(preview.body.routes.length===1,'The original compiler did not retain the selected route.');
await page.locator('#package-name').fill(packageName);
const saved=await clickApi(page.locator('#save'),'/api/save');
const loaded=await read('/api/load?name='+encodeURIComponent(packageName));
check(Buffer.from(loaded.specText,'utf8').equals(fs.readFileSync(ready.specPath)),'The saved package did not retain the original source bytes.');
check(loaded.plan.operations[0].oauthConnection.grantId===authorization.grantId,'The saved plan lost the selected reviewed grant.');
check(loaded.plan.operations[0].amountAtomic===ready.paymentExample.amountAtomic,'The exact original atomic price changed.');
const before=await control('status');
const started=await clickApi(page.locator('#start-preview'),'/api/start');
const unpaid=await clickApi(page.locator('#check-routes'),'/api/accept');
check(unpaid.body.acceptance?.summary?.passed===1&&unpaid.body.acceptance?.summary?.total===1,'The original unpaid challenge did not match its compiled offer.');
const after=await control('status');
check(JSON.stringify(before.peer.counters)===JSON.stringify(after.peer.counters),'The unpaid challenge contacted the OAuth peer.');
await screenshot('01-original-provider-and-seller.png');
await clickApi(page.locator('#stop'),'/api/stop');
const result={packageName,authorization,routeId:preview.body.routes[0].id,sourceSha256:hash(fs.readFileSync(ready.specPath)),
 binding:binding.body.oauthConnection,atomicPrice:ready.paymentExample.amountAtomic,
 challenge:{mode:started.body.mode,summary:unpaid.body.acceptance.summary,providerCallsDuringChallenge:0},
 compiledRoutes:preview.body.routes.length,pageErrors:[...pageErrors],externalRequests:[...externalRequests]};
record('original_source_authorization_compiler_and_unpaid_challenge',result);
return result;
